// VIOLATION: high-level OrderService directly depends on low-level MySQLDatabase
class OrderService {
    private MySQLDatabase db = new MySQLDatabase(); // concrete dependency!
    void save(Order o) { db.insert(o); }
}

// DIP: both depend on the abstraction (interface)
interface OrderRepository { void save(Order o); }
class MySQLOrderRepository implements OrderRepository { /* SQL impl */ }
class OrderService {
    private final OrderRepository repo; // abstraction!
    OrderService(OrderRepository repo) { this.repo = repo; } // injected
    void save(Order o) { repo.save(o); }
}

// Interface (abstraction)
public interface UserRepository {
    Optional<User> findById(Long id);
    User save(User user);
}

// Concrete implementation
@Repository
public class JpaUserRepository implements UserRepository {
    // JPA implementation
}

// High-level service depends on abstraction, not concrete
@Service
public class UserService {
    private final UserRepository userRepository; // interface!

    // Constructor injection — Spring wires JpaUserRepository here
    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }
}

// DIP violation: OrderService hardcodes its dependency
class OrderService {
    // This line makes OrderService FOREVER coupled to EmailNotificationService
    private NotificationService notifier = new EmailNotificationService();

    void placeOrder(Order o) {
        processOrder(o);
        notifier.notify("Order placed"); // cannot swap to SMS without changing this class
    }
}

// DIP: inject the dependency
class OrderService {
    private final NotificationService notifier;
    OrderService(NotificationService notifier) { this.notifier = notifier; }
    // Now pass EmailNotificationService or SmsNotificationService from outside
}

// With DIP: easy to test — inject a mock UserRepository
@ExtendWith(MockitoExtension.class)
class UserServiceTest {
    @Mock
    UserRepository userRepository; // mock of the interface

    @InjectMocks
    UserService userService; // gets the mock injected

    @Test
    void shouldReturnUserById() {
        User user = new User(1L, "Alice");
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));
        User result = userService.getUser(1L);
        assertEquals("Alice", result.getName());
        // No real database needed!
    }
}
